export const PRIVACY_COPY={
 tr:{title:'Gizlilik ve lisanslar',policy:'Gizlilik politikası',support:'Destek',credits:'Lisanslar ve kaynaklar',reset:'Tüm oyun verilerini sil',confirm:'Fotoğraflar, karakter isimleri, rekorlar ve tercihler bu uygulamadan silinecek. Bu işlem geri alınamaz. İşletim sistemi yedeklerini silmez.',erase:'Evet, verileri sil',cancel:'Vazgeç',error:'Veriler silinemedi. Tekrar dene.',close:'Kapat',sections:[
  ['Kapsam ve iletişim','Popzuno’ün çevrimdışı mobil ve taşınabilir oyun sürümleri. Geliştirici: Mert Bekisoglu. Gizlilik ve destek: mertbek@gmail.com. Son güncelleme: 29 Ekim 2026.'],
  ['Cihazda işlenen veriler','İsteğe bağlı karakter isimleri, seçilen fotoğrafların küçültülmüş/kadrajlanmış kopyaları, kadraj ayarları, oyun rekorları, etaplar, dil ve ses/titreşim tercihleri yerel uygulama alanında tutulur. Fotoğraf seçmezsen varsayılan çizimlerle oynayabilirsin.'],
  ['Fotoğraf ve yüz bulma','Yalnızca seçtiğin fotoğraf işlenir. Yüzün konumunu bulma ve kırpma cihazda yapılır; kişiyi tanımlayan yüz şablonu, yüz tanıma hesabı veya sunucuya fotoğraf yükleme yoktur. Kullanma iznin olan fotoğrafları seç; başkalarının ve çocukların fotoğraflarında gerekli izinleri al. Kamera yalnızca iOS sistem seçicisinden kendin seçersen kullanılır. Android sistem seçicisiyle tekil fotoğraf erişimi kullanır; tüm galeri izni istenmez.'],
  ['Sunucuya aktarım ve paylaşım','Oyunda hesap, reklam, takip, analiz, bulut liderlik tablosu veya kendi sunucumuza veri gönderimi yoktur. Satın alma ve mağazanın kendi işlemleri Apple/Google tarafından yönetilir. Sonuç paylaşımı sistem/tarayıcı paylaşımı veya panosuyla yalnızca sen başlatırsan yapılır; fotoğraf ve isim eklenmez. Destek e-postası gönderirsen mesajın ve adresin e-posta sağlayıcısı üzerinden bize ulaşır; istemediğin özel fotoğrafları gönderme.'],
  ['Saklama, silme ve yedekler','Veriler sen silene kadar yerel kayıtta kalır. Sevdiklerim ekranı tekil fotoğrafları kaldırır; bu ekrandaki tüm verileri sil seçeneği isimleri, fotoğrafları, rekorları ve tercihleri de kaldırır. Orijinal galeri fotoğrafları değişmez. iOS işletim sistemi ayarlarına göre uygulama verileri sistem yedeklerine girebilir; önceki yedekleri uygulama silemez. Android uygulama yedeklemesi kapalıdır. Taşınabilir sürümün kaydı tarayıcı tarafından yönetilir. Sistem/tarayıcı yedeklerini kendi ayarlarından yönetebilirsin. Destek mesajları yanıt için gerektiği sürece tutulur; silme talepleri için iletişime geçebilirsin.'],
  ['Dış sayfalar ve değişiklikler','Destek/gizlilik web sayfasını veya e-posta uygulamasını açarsan bu hizmetlerin kendi bağlantı, güvenlik ve gizlilik işlemleri geçerlidir. Oyun fotoğrafları bu sayfalara otomatik gönderilmez. Veri davranışı değişirse politika ve mağaza beyanları yeni sürümden önce güncellenir.']
 ]},
 en:{title:'Privacy and licenses',policy:'Privacy policy',support:'Support',credits:'Licenses and sources',reset:'Delete all game data',confirm:'Photos, character names, records and preferences will be deleted from this app. This cannot be undone. Operating-system backups are not deleted.',erase:'Yes, delete data',cancel:'Cancel',error:'Could not delete data. Please try again.',close:'Close',sections:[
  ['Scope and contact','Offline mobile and portable versions of Popzuno. Developer: Mert Bekisoglu. Privacy and support: mertbek@gmail.com. Updated 29 October 2026.'],
  ['Data processed on your device','Optional character names, resized/cropped copies of selected photos, framing settings, records, stages, language and audio/haptic preferences are stored in the app’s local storage. Photos are optional; default illustrated characters are available.'],
  ['Photos and face detection','Only the photo you select is processed. Face location and cropping run on your device; there is no identifying face template, face-recognition account or photo upload. Use photos you have permission to use, including the necessary permission for other people and children. The camera is used only if you choose it through the iOS system picker. Android uses a system picker for individual images without broad gallery permission.'],
  ['Transfers and sharing','The game has no account, ads, tracking, analytics, cloud leaderboard or transmission to our own servers. Apple/Google handle their store and purchase transactions. Result sharing uses the system/browser share interface or clipboard only when you initiate it; no photos or names are attached. If you email support, your message and email address reach us through the email provider; do not send private photos unnecessarily.'],
  ['Retention, deletion and backups','Local data remains until you delete it. Your people removes individual photos; Delete all game data also removes names, records and preferences. Original gallery images are not changed. Depending on your settings, iOS app data may enter operating-system backups, which the app cannot delete retrospectively. Android app backup is disabled. Portable-version storage is managed by your browser. Manage system/browser backups in their settings. Support emails are retained as needed to handle the request; contact us to request deletion.'],
  ['External pages and changes','Opening support/privacy pages or an email app involves those services’ own connection, security and privacy practices. Game photos are not automatically sent to those pages. Changes to data handling require updated policy and store disclosures before release.']
 ]},
 it:{title:'Privacy e licenze',policy:'Informativa sulla privacy',support:'Assistenza',credits:'Licenze e fonti',reset:'Elimina tutti i dati di gioco',confirm:'Foto, nomi, record e preferenze saranno eliminati dall’app. L’operazione è irreversibile e non elimina i backup del sistema.',erase:'Sì, elimina i dati',cancel:'Annulla',error:'Impossibile eliminare i dati. Riprova.',close:'Chiudi',sections:[
  ['Ambito e contatti','Versioni mobili e portatili offline di Popzuno. Sviluppatore: Mert Bekisoglu. Privacy e assistenza: mertbek@gmail.com. Aggiornamento: 29 ottobre 2026.'],
  ['Dati locali','Nomi facoltativi, copie ridimensionate/ritagliate delle foto selezionate, inquadratura, record, livelli, lingua e preferenze audio/aptiche restano nella memoria locale dell’app. Puoi giocare senza foto usando i personaggi illustrati.'],
  ['Foto e volti','Si elabora solo la foto scelta. Rilevamento della posizione del volto e ritaglio avvengono sul dispositivo: nessun modello identificativo personale, account di riconoscimento o caricamento. Usa foto autorizzate, con i permessi necessari per altre persone e minori. La fotocamera si usa solo se scelta nel selettore iOS; Android usa il selettore di immagini senza accesso generale alla galleria.'],
  ['Trasferimenti e condivisione','Nessun account, pubblicità, tracciamento, analisi, classifica cloud o invio ai nostri server. Apple/Google gestiscono gli acquisti del negozio. La condivisione dei risultati o gli appunti si attivano solo su tua richiesta, senza foto o nomi. Un’email all’assistenza trasmette messaggio e indirizzo tramite il provider email: evita foto private non necessarie.'],
  ['Conservazione e cancellazione','I dati locali restano finché non li elimini. I miei cari elimina singole foto; l’opzione di eliminazione totale rimuove anche nomi, record e preferenze. Le foto originali non cambiano. iOS può includere i dati nei backup del sistema secondo le tue impostazioni; l’app non elimina backup precedenti. Il backup Android è disattivato. Nel formato portatile i dati sono gestiti dal browser. Gestisci i backup nelle impostazioni del sistema/browser. Le email di assistenza restano per il tempo necessario alla richiesta; puoi chiederne la cancellazione.'],
  ['Servizi esterni','Pagine di supporto/privacy e app email applicano le proprie regole di connessione, sicurezza e privacy. Le foto non vengono inviate automaticamente. Eventuali cambiamenti richiedono l’aggiornamento dell’informativa e delle dichiarazioni dei negozi prima della pubblicazione.']
 ]},
 es:{title:'Privacidad y licencias',policy:'Política de privacidad',support:'Soporte',credits:'Licencias y fuentes',reset:'Eliminar todos los datos',confirm:'Se eliminarán fotos, nombres, récords y preferencias de esta app. No se puede deshacer y no elimina las copias del sistema.',erase:'Sí, eliminar los datos',cancel:'Cancelar',error:'No se pudieron eliminar los datos. Inténtalo de nuevo.',close:'Cerrar',sections:[
  ['Ámbito y contacto','Versiones móviles y portátiles sin conexión de Popzuno. Desarrollador: Mert Bekisoglu. Privacidad y soporte: mertbek@gmail.com. Actualizado: 29 de octubre de 2026.'],
  ['Datos locales','Nombres opcionales, copias reducidas/recortadas de las fotos elegidas, encuadre, récords, etapas, idioma y preferencias de sonido/vibración se guardan localmente. Puedes jugar sin fotos con los personajes ilustrados.'],
  ['Fotos y rostros','Solo se procesa la foto elegida. La localización del rostro y el recorte se realizan en el dispositivo; no hay plantilla identificativa personal, cuenta de reconocimiento ni subida de fotos. Usa imágenes autorizadas y obtén los permisos necesarios para otras personas y menores. La cámara solo se usa si la eliges en el selector de iOS. Android utiliza el selector del sistema sin acceso general a la galería.'],
  ['Transferencias y compartir','No hay cuentas, anuncios, seguimiento, analítica, clasificación en la nube ni envío a nuestros servidores. Apple/Google gestionan las compras de la tienda. Compartir resultados o copiarlos al portapapeles solo ocurre si lo solicitas, sin fotos ni nombres. Los correos al soporte envían el mensaje y tu dirección mediante el proveedor de correo; evita adjuntar fotos privadas innecesarias.'],
  ['Conservación y borrado','Los datos locales permanecen hasta que los elimines. Mi gente borra fotos individuales; el borrado total también elimina nombres, récords y preferencias. Las imágenes originales no se modifican. iOS puede incluir los datos en copias del sistema según tus ajustes; la app no borra copias anteriores. Las copias Android están desactivadas. La versión portátil usa el almacenamiento del navegador. Gestiona las copias en sus ajustes. Los correos de soporte se conservan el tiempo necesario para la solicitud; puedes pedir su eliminación.'],
  ['Servicios externos','Las páginas de soporte/privacidad y las apps de correo aplican sus propias prácticas de conexión, seguridad y privacidad. No reciben automáticamente las fotos del juego. Los cambios en el tratamiento de datos requieren actualizar la política y las declaraciones de las tiendas antes de publicar.']
 ]},
 de:{title:'Datenschutz und Lizenzen',policy:'Datenschutzerklärung',support:'Support',credits:'Lizenzen und Quellen',reset:'Alle Spieldaten löschen',confirm:'Fotos, Namen, Rekorde und Einstellungen werden aus dieser App gelöscht. Dies ist nicht rückgängig zu machen und löscht keine Systembackups.',erase:'Ja, Daten löschen',cancel:'Abbrechen',error:'Daten konnten nicht gelöscht werden. Bitte erneut versuchen.',close:'Schließen',sections:[
  ['Geltungsbereich und Kontakt','Offline-Mobil- und portable Versionen von Popzuno. Entwickler: Mert Bekisoglu. Datenschutz und Support: mertbek@gmail.com. Stand: 29. Oktober 2026.'],
  ['Lokale Daten','Optionale Namen, verkleinerte/zugeschnittene Kopien gewählter Fotos, Bildausschnitte, Rekorde, Stufen, Sprache und Ton-/Vibrationseinstellungen werden lokal gespeichert. Ohne Fotos kannst du mit gezeichneten Figuren spielen.'],
  ['Fotos und Gesichter','Nur das ausgewählte Foto wird verarbeitet. Gesichtslokalisierung und Zuschnitt erfolgen auf dem Gerät; keine personenbezogene Gesichtsvorlage, kein Erkennungskonto und kein Foto-Upload. Verwende erlaubte Fotos und hole nötige Einwilligungen für andere Personen und Kinder ein. Die Kamera wird nur auf deine Auswahl im iOS-Systemdialog genutzt. Android verwendet die Systembildauswahl ohne allgemeinen Galeriezugriff.'],
  ['Übertragung und Teilen','Keine Konten, Werbung, Nachverfolgung, Analyse, Cloud-Rangliste oder Übertragung an unsere Server. Apple/Google verwalten Storekäufe. Ergebnisse werden nur auf deinen Wunsch über System-/Browserfreigabe oder Zwischenablage geteilt, ohne Fotos und Namen. Support-E-Mails übertragen Nachricht und Adresse über den E-Mail-Anbieter; sende keine unnötigen privaten Fotos.'],
  ['Speicherung und Löschung','Lokale Daten bleiben bis zur Löschung. Meine Liebsten entfernt einzelne Fotos; die vollständige Löschung entfernt auch Namen, Rekorde und Einstellungen. Originalfotos bleiben unverändert. iOS kann App-Daten je nach Einstellungen in Systembackups aufnehmen; frühere Backups kann die App nicht löschen. Android-Backups sind deaktiviert. Portable Daten verwaltet der Browser. Backups verwaltest du in System-/Browsereinstellungen. Supportnachrichten bleiben so lange wie für die Anfrage nötig; eine Löschung kann angefragt werden.'],
  ['Externe Dienste','Für Support-/Datenschutzseiten und E-Mail-Apps gelten deren Verbindungs-, Sicherheits- und Datenschutzverfahren. Spielfotos werden nicht automatisch übertragen. Vor Änderungen der Datenverarbeitung werden Erklärung und Storeangaben aktualisiert.']
 ]},
 ru:{title:'Конфиденциальность и лицензии',policy:'Политика конфиденциальности',support:'Поддержка',credits:'Лицензии и источники',reset:'Удалить все данные игры',confirm:'Фото, имена, рекорды и настройки будут удалены из приложения. Отменить это нельзя. Резервные копии системы не удаляются.',erase:'Да, удалить данные',cancel:'Отмена',error:'Не удалось удалить данные. Попробуй ещё раз.',close:'Закрыть',sections:[
  ['Область действия и контакты','Офлайн-версии Popzuno для мобильных устройств и браузера. Разработчик: Mert Bekisoglu. Конфиденциальность и поддержка: mertbek@gmail.com. Обновлено 29 октября 2026 года.'],
  ['Локальные данные','Необязательные имена, уменьшенные/обрезанные копии выбранных фото, кадрирование, рекорды, этапы, язык и настройки звука/вибрации сохраняются локально. Можно играть без фотографий с рисованными персонажами.'],
  ['Фото и лица','Обрабатывается только выбранное фото. Поиск положения лица и обрезка выполняются на устройстве; нет идентифицирующего шаблона лица, аккаунта распознавания или загрузки фото на сервер. Используй разрешённые снимки и получай необходимые согласия для других людей и детей. Камера используется только при её выборе в системном диалоге iOS. Android использует системный выбор отдельных изображений без общего доступа к галерее.'],
  ['Передача и обмен','Нет аккаунтов, рекламы, отслеживания, аналитики, облачной таблицы или передачи на наши серверы. Покупки в магазинах обрабатывают Apple/Google. Результат передаётся через системное/браузерное меню или буфер обмена только по твоему действию, без фото и имён. Письмо поддержке передаёт сообщение и адрес через почтового провайдера; не отправляй лишние личные фото.'],
  ['Хранение и удаление','Локальные данные остаются до удаления. Близкие удаляет отдельные фото; полное удаление также стирает имена, рекорды и настройки. Исходные фото не меняются. В зависимости от настроек iOS данные могут попасть в резервную копию системы; приложение не удаляет прежние копии. Резервное копирование Android отключено. Данные переносной версии управляются браузером. Копиями управляй в настройках системы/браузера. Письма поддержке хранятся по необходимости для запроса; можно запросить удаление.'],
  ['Внешние службы','Для страниц поддержки/политики и почтовых приложений действуют их правила соединения, безопасности и конфиденциальности. Фото игры автоматически туда не отправляются. Изменения обработки данных требуют обновления политики и сведений магазинов до выпуска.']
 ]}
};
export function privacyCopy(language){return PRIVACY_COPY[language]??PRIVACY_COPY.en;}
